; reads.asm -- chapter 20: reading the VRAM in the paper's lines
; generated by gen20.py
        INCLUDE "msx.inc"
        OUTPUT "reads.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
BOX_EMPTY EQU 1             ; the library's two boxes, characters 1 and 2
BOX_FULL  EQU 2
; 128 bytes of text read back into the RAM in the paper's lines, with INIR and
; with INI and JP NZ, one a frame; then, with the display off, both shown.
buf1    EQU VARS + $20          ; what INIR read
buf2    EQU buf1 + 128          ; what INI and JP NZ read
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, l_orig
        call puts
        ld b, 6
        ld c, 0
        ld hl, l_inir
        call puts
        ld b, 12
        ld c, 0
        ld hl, l_ini
        call puts
        VRAM_WRITE $1820        ; the text, the display off
        ld hl, text
        ld b, 128
        ld c, VDP_DATA
        otir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; display on, and the frame's signal on
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, uj         ; 11
u5s:    ld de, 1217
u5:     dec de
        ld a, d
        or e
        jr nz, u5
        ld c, 0
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
        nop
        jp ug             ; 11
uj:
u6s:    ld de, 831
u6:     dec de
        ld a, d
        or e
        jr nz, u6
        nop
        nop
ug:
r1:
        ld a, $20               ;  8
        out (VDP_CTRL), a       ; 12
        ld a, $18               ;  8: bit 6 is 0, a read
        out (VDP_CTRL), a       ; 12: and the VDP reads ahead
        ld hl, buf1             ; 11
        ld bc, 128 * 256 + VDP_DATA   ; 11
        inir                    ; 23 a byte, 18 the last
z1:
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, vj         ; 11
v5s:    ld de, 1217
v5:     dec de
        ld a, d
        or e
        jr nz, v5
        ld c, 0
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
        nop
        jp vg             ; 11
vj:
v6s:    ld de, 831
v6:     dec de
        ld a, d
        or e
        jr nz, v6
        nop
        nop
vg:
r2:
        ld a, $20               ;  8
        out (VDP_CTRL), a       ; 12
        ld a, $18               ;  8: bit 6 is 0, a read
        out (VDP_CTRL), a       ; 12: and the VDP reads ahead
        ld hl, buf2             ; 11
        ld bc, 128 * 256 + VDP_DATA   ; 11
x2:     ini                     ; 18
        jp nz, x2               ; 11: 29 a byte
z2:
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        VDP_REG 1, $A0          ; display off, to show what was read
        VRAM_WRITE $18E0
        ld hl, buf1
        ld b, 128
        otir
        VRAM_WRITE $19A0
        ld hl, buf2
        ld b, 128
        otir
        VDP_REG 1, $C0          ; and on again
done:   jr done

; isr: the frame's interrupt, taken once, to start in step with the picture
isr:    push af
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        pop af
        ei
        ret
l_orig:        db "WRITTEN:", 0
l_inir:        db "READ WITH INIR, 23 T A BYTE:", 0
l_ini:        db "READ WITH INI/JP NZ, 29 T:", 0
        ALIGN 256
text:   db "ABCDEFGHIJKLMNOPQRSTUVWXYZ012345ABCDEFGHIJKLMNOPQRSTUVWXYZ012345ABCDEFGHIJKLMNOPQRSTUVWXYZ012345ABCDEFGHIJKLMNOPQRSTUVWXYZ012345"

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
